/* =============================================================
   FF_Galerie — galerie-core.js
   Noyau partagé entre tous les types de galerie (peinture, sculpture…)
   Config (surcharger avant ce script) :
     window.GALERIE_TOILES_PATH    (défaut: 'data/toiles.json') — mono-type
     window.GALERIE_OEUVRES_PATHS  (tableau, multi-types) — prioritaire
                                    ex: ['data/oeuvres/peinture.json',
                                         'data/oeuvres/sculpture.json']
     window.GALERIE_SALLES_PATH    (défaut: 'data/salles.json')
     window.GALERIE_HOME           (défaut: 'index.html')
   ============================================================= */

const GALERIE_CFG = {
  toiles:     window.GALERIE_TOILES_PATH  || 'data/toiles.json',
  oeuvresPaths: window.GALERIE_OEUVRES_PATHS || null, /* tableau ou null */
  salles:     window.GALERIE_SALLES_PATH  || 'data/salles.json',
  home:       window.GALERIE_HOME         || 'index.html',
  infos:      window.GALERIE_INFOS_PATH   || 'infos.html',
  contact:    window.GALERIE_CONTACT_PATH || 'contact.html',
  assetsBase: window.GALERIE_ASSETS_BASE  || '' /* '' pour Fred, '../../' pour artistes */
};

/* Charge les œuvres et retourne toujours un dict { peinture: {tailles,toiles},
   sculpture: {gabarits,pieces} } quel que soit le format source. */
function _chargerOeuvres() {
  if (GALERIE_CFG.oeuvresPaths && Array.isArray(GALERIE_CFG.oeuvresPaths)) {
    /* Multi-fichiers : déduit le type depuis le nom de fichier oeuvres/<type>.json */
    return Promise.all(GALERIE_CFG.oeuvresPaths.map(function(path) {
      var m = path.match(/oeuvres\/([^/]+)\.json/);
      var type = m ? m[1] : 'peinture';
      return fetch(path + '?v=' + Date.now())
        .then(function(r) { if (!r.ok) throw new Error(r.status); return r.json(); })
        .then(function(data) { return { type: type, data: data }; });
    })).then(function(arr) {
      var dict = {};
      arr.forEach(function(x) { dict[x.type] = x.data; });
      return dict;
    });
  }
  /* Mono-fichier (ancien) : déduit le type depuis la structure du JSON */
  return fetch(GALERIE_CFG.toiles + '?v=' + Date.now())
    .then(function(r) { if (!r.ok) throw new Error(r.status); return r.json(); })
    .then(function(data) {
      var type = (data && data.pieces) ? 'sculpture' : 'peinture';
      var dict = {}; dict[type] = data; return dict;
    });
}

    let salleCourante = 1;
    let TOTAL_SALLES = 0; // défini dynamiquement après chargement JSON
    /* Chiffres romains generes a la volee (plus de liste figee a 10 entrees :
       au-dela de X la nav affichait 'undefined'). Le Proxy preserve la syntaxe
       d'indexation NOMS_ROMAINS[i] partout (0-based -> toRoman(i+1)), y compris
       quand la liste est passee a creerPlancher, sans toucher aux appelants. */
    function toRoman(n) {
      n = Math.floor(n);
      if (!(n >= 1)) return '';
      var map = [[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],
                 [50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']];
      var r = '';
      for (var k = 0; k < map.length; k++) {
        while (n >= map[k][0]) { r += map[k][1]; n -= map[k][0]; }
      }
      return r;
    }
    const NOMS_ROMAINS = new Proxy({}, {
      get: function(_t, prop) {
        var i = Number(prop);
        return Number.isInteger(i) ? toRoman(i + 1) : undefined;
      }
    });
    const conteneur  = document.getElementById('conteneurSalles');
    const btnPrev    = document.getElementById('btnPrecedent');
    const btnNext    = document.getElementById('btnSuivant');
    const numSalleEl = document.getElementById('numSalle');
    const dotsEl     = document.querySelectorAll('.dot');
    let navMode = 'c';

    /* Portes injectées dynamiquement après chargement JSON */

    function mettreAJourNav() {
      /* Navigation mobile */
      const mobG = document.getElementById('navMobG');
      const mobD = document.getElementById('navMobD');
      const mobInfo = document.getElementById('navMobInfo');
      if (mobG) mobG.disabled = salleCourante === 1;
      if (mobD) mobD.disabled = salleCourante === TOTAL_SALLES;
      if (mobInfo) mobInfo.textContent = NOMS_ROMAINS[salleCourante-1] + ' / ' + NOMS_ROMAINS[TOTAL_SALLES-1];
      /* Flèches latérales fixes (PC) — cachées en bord de galerie */
      var _flG = document.querySelector('.nav-cote-g');
      var _flD = document.querySelector('.nav-cote-d');
      if (_flG) _flG.classList.toggle('hidden', salleCourante <= 1);
      if (_flD) _flD.classList.toggle('hidden', salleCourante >= TOTAL_SALLES);
      /* Flèches mode A */

      /* Pastille */
      const pastille = document.getElementById('navPastille');
      if (pastille) pastille.textContent =
        'Salle ' + NOMS_ROMAINS[salleCourante - 1] + ' / ' + NOMS_ROMAINS[TOTAL_SALLES - 1];

      /* Mini dots */
      document.querySelectorAll('.ndot').forEach((d, i) => d.classList.toggle('actif', i + 1 === salleCourante));

      /* Portes mode C */
      document.querySelectorAll('.porte').forEach(p => {
        const murId = parseInt(p.dataset.murId);
        const cote  = p.dataset.cote;

        /* Porte de sortie : dernière salle côté droit → Accueil */
        if (murId === TOTAL_SALLES && cote === 'd') {
          p.classList.remove('invisible');
          p.dataset.cible = 'accueil';
          p.querySelector('.porte-nom').textContent = '← Accueil';
          return;
        }

        const cible  = cote === 'g' ? murId - 1 : murId + 1;
        p.dataset.cible = cible;
        const visible = cible >= 1 && cible <= TOTAL_SALLES;
        p.classList.toggle('invisible', !visible);
        if (visible) {
          const nom = 'Salle ' + NOMS_ROMAINS[cible - 1];
          p.querySelector('.porte-nom').textContent =
            cote === 'g' ? '← ' + nom : nom + ' →';
        }
      });
    }

    function allerSalle(n) {
      salleCourante = Math.max(1, Math.min(TOTAL_SALLES, n));
      // Calcul dynamique : chaque salle = 1/TOTAL_SALLES du conteneur
      conteneur.style.transform = salleCourante > 1
        ? 'translateX(-' + ((salleCourante-1)/TOTAL_SALLES*100).toFixed(4) + '%)'
        : '';
      if (numSalleEl) numSalleEl.textContent = salleCourante;
      if (btnPrev) btnPrev.disabled = salleCourante === 1;
      if (btnNext) btnNext.disabled = salleCourante === TOTAL_SALLES;
      dotsEl.forEach((d, i) => d.classList.toggle('actif', i + 1 === salleCourante));
      mettreAJourNav();
    }

    if (btnPrev) btnPrev.addEventListener('click', () => allerSalle(salleCourante - 1));
    if (btnNext) btnNext.addEventListener('click', () => allerSalle(salleCourante + 1));

    /* ── Flèches latérales fixes (PC) ──
       Présentes en permanence à gauche/droite, complément des portes
       (qui peuvent avoir des positions/tailles différentes selon le type
       de salle, rendant la transition moins évidente). Cachées sur mobile
       (la nav-mobile en bas suffit). Visibilité gérée dans mettreAJourNav. */
    function _creerFlecheLaterale(cote, label) {
      var b = document.createElement('button');
      b.className = 'nav-cote nav-cote-' + cote;
      b.setAttribute('aria-label', label);
      b.innerHTML = cote === 'g' ? '&#8249;' : '&#8250;';
      b.addEventListener('click', function() {
        allerSalle(salleCourante + (cote === 'g' ? -1 : 1));
      });
      document.body.appendChild(b);
      return b;
    }
    if (!document.querySelector('.nav-cote-g')) _creerFlecheLaterale('g', 'Salle précédente');
    if (!document.querySelector('.nav-cote-d')) _creerFlecheLaterale('d', 'Salle suivante');

    /* ── Swipe horizontal pour changer de salle (mobile) ── */
    let swipeGalX = null, swipeGalY = null;
    conteneur.addEventListener('touchstart', e => {
      swipeGalX = e.touches[0].clientX;
      swipeGalY = e.touches[0].clientY;
    }, {passive:true});
    conteneur.addEventListener('touchend', e => {
      if (swipeGalX === null) return;
      const dx = e.changedTouches[0].clientX - swipeGalX;
      const dy = Math.abs(e.changedTouches[0].clientY - swipeGalY);
      // Swipe valide si horizontal > 50px ET dominant (> déplacement vertical)
      if (Math.abs(dx) > 50 && Math.abs(dx) > dy * 1.2) {
        if (dx < 0) allerSalle(salleCourante + 1);
        else        allerSalle(salleCourante - 1);
      }
      swipeGalX = null; swipeGalY = null;
    }, {passive:true});

    /* Mode C permanent */
    document.body.setAttribute('data-nav', 'c');
    mettreAJourNav();

    // NB: le hash (#salle-ID) est traité après chargement JSON (plus bas dans Promise.all)
    // pour pouvoir mapper l'id JSON → index d'affichage

    document.addEventListener('keydown', e => {
      var _mo = document.getElementById('modalOverlay'); if (_mo && _mo.classList.contains('visible')) {
        if (e.key === 'Escape') fermerModal();
        return;
      }
      if (e.key === 'ArrowRight') allerSalle(salleCourante + 1);
      if (e.key === 'ArrowLeft')  allerSalle(salleCourante - 1);
    });

    const modalOverlay = document.getElementById('modalOverlay');

    // Hauteur plancher selon largeur écran
    function hauteurPlancher() {
      return window.innerWidth <= 600 ? 90 : 110;
    }

