    function creerPlancher(salleIdx, totalSalles, sallesData, nomsRomains, salle) {
      const zone = document.createElement('div');
      zone.className = 'zone-basse';

      // ── Mur inférieur avec portes ──
      const murBas = document.createElement('div');
      murBas.className = 'mur-inferieur';
      /* Couleur paramétrable par salle — default #111 (= ancien hardcodé,
         égal au body global pour rester invisible si non personnalisé).
         setProperty avec 'important' garantit l'override de toutes les
         règles CSS du fichier galerie.css ET galerie-sculpture.css qui
         peuvent cibler .mur-inferieur en shorthand background. */
      murBas.style.setProperty('background-color', (salle && salle.couleur_mur_bas) || '#111', 'important');

      function makePorte(cote) {
        const btn = document.createElement('button');
        btn.className = 'porte-mur';
        const estGauche = cote === 'g';
        const cibleIdx = estGauche ? salleIdx - 1 : salleIdx + 1;

        // Rend la porte invisible si hors limites
        if (estGauche && salleIdx <= 1) { btn.className += ' invisible'; }

        // Nom de la porte : utilise le vrai nom depuis le JSON
        const sallePrev = sallesData[salleIdx - 2]; // 0-based
        const salleNext = sallesData[salleIdx];     // 0-based
        const nomPrev = sallePrev ? (sallePrev.nom || "Salle " + nomsRomains[salleIdx - 2]) : "";
        const nomNext = salleNext ? (salleNext.nom || "Salle " + nomsRomains[salleIdx])     : "";

        let nom = "";
        if (!estGauche && salleIdx >= totalSalles) nom = "Retour";
        else if (estGauche && salleIdx > 1)        nom = "\u2190 " + nomPrev;
        else if (!estGauche && salleIdx < totalSalles) nom = nomNext + " \u2192";

        btn.innerHTML = '<span class="pm-nom"></span><div class="pm-ouverture"><span class="pm-fleche">'+(estGauche?"\u2039":"\u203a")+'</span></div>';
        btn.querySelector(".pm-nom").textContent = nom; /* A3 : nom de salle injecte en textContent (insensible a < & " ) */
        btn.addEventListener("click", function() {
          if (!estGauche && salleIdx >= totalSalles) { window.location.href = "index.html"; return; }
          allerSalle(cibleIdx);
        });
        return btn;
      }
      murBas.appendChild(makePorte("g"));
      murBas.appendChild(document.createElement("div")); // spacer central
      murBas.appendChild(makePorte("d"));
      zone.appendChild(murBas);

      // ── Sol : parquet (defaut CSS) ou personnalise par salle (couleur + parquet/uni) ──
      const sol = document.createElement("div");
      sol.className = "plancher-sol";
      /* Si la salle definit un sol custom (peinture), on l'applique inline en
         !important par-dessus le CSS d'origine. Sans champ -> aspect inchange. */
      if (salle && (salle.couleur_sol || salle.sol_type)) {
        var _solC = salle.couleur_sol || '#4a3018';
        var _solBg;
        if (salle.sol_type === 'uni') {
          _solBg = _solC;
        } else {
          /* Parquet teinte : memes lames que l'apercu admin (.scene-plancher) sur la couleur choisie */
          _solBg = 'repeating-linear-gradient(90deg,rgba(0,0,0,.22) 0,rgba(0,0,0,.22) 1px,transparent 1px,transparent 60px),'
                 + 'repeating-linear-gradient(to bottom,transparent 0,transparent 14px,rgba(0,0,0,.15) 14px,rgba(0,0,0,.15) 16px),'
                 + _solC;
        }
        sol.style.setProperty('background', _solBg, 'important');
        sol.classList.add('sol-custom');
      }
      const sv = document.createElement("div");
      sv.className = "silhouettes-sol";
      sv.innerHTML = genererSilhouettes(150); // placeholder — remplacé après layout
      sol.appendChild(sv);
      zone.appendChild(sol);

      // 2e passe mobile : mesure la hauteur réelle du plancher (flex:1 variable)
      if (window.innerWidth < 901) {
        requestAnimationFrame(function() {
          var h = sol.clientHeight;
          if (h > 30) {
            var vhSvg = Math.round(h * 420 / (sol.clientWidth || 375));
            sv.innerHTML = genererSilhouettes(vhSvg);
          }
        });
      }

      // Panneaux de navigation sur pied (visibles desktop via CSS)
      [
        { href:GALERIE_CFG.infos,   cls:"pan-infos",   txt:"← Infos"   },
        { href:GALERIE_CFG.contact, cls:"pan-contact", txt:"Contact ↓" },
        { href:GALERIE_CFG.home,    cls:"pan-accueil", txt:"Accueil →" }
      ].forEach(function(p) {
        const a = document.createElement("a");
        a.className = "panneau-nav " + p.cls;
        a.href = p.href;
        a.innerHTML = "<span class=\"pan-board\">" + p.txt + "</span>" +
                      "<span class=\"pan-pole\"></span>" +
                      "<span class=\"pan-base\"></span>";
        zone.appendChild(a);
      });

      return zone;
    }

    function genererSilhouettes(vhParam) {
      const pool = [...SIL_DATA].sort(() => Math.random() - 0.5);

      // ── 4 plans de profondeur ──────────────────────────────────────
      // Rendu arrière → avant (algorithme du peintre)
      const VW = 420, VH = (vhParam && vhParam > 30) ? vhParam : 150;

      // Nombre aléatoire de silhouettes par plan
      const isMobile = window.innerWidth < 901;
      const nb = {
        tl: 2 + Math.floor(Math.random() * 4), // très lointain : 2–5 (mobile uniquement)
        lo: 2 + Math.floor(Math.random() * 3), // lointain      : 2–4
        mi: 2 + Math.floor(Math.random() * 2), // milieu        : 2–3
        av: 1 + Math.floor(Math.random() * 2)  // avant-scène   : 1–2
      };

      // Très lointain restauré sur GSM (supprimé desktop : trop petit + conflits panneaux)
      // Toujours 4 entrées → ZONES[planIdx] jamais undefined
      // nbMax:0 sur desktop → plan.sils vide → forEach le saute
      // FLOOR : marge nav sur mobile (22%), desktop garde VH plein
      const FLOOR = isMobile ? VH * 0.78 : VH;
      const PLANS = [
        { yFloor: FLOOR * 0.21, hBase: 32, opacite: 0.55, nbMax: isMobile ? nb.tl : 0 }, // très lointain
        { yFloor: FLOOR * 0.35, hBase: 42, opacite: 0.68, nbMax: nb.lo },                 // lointain
        { yFloor: FLOOR * 0.65, hBase: 64, opacite: 0.75, nbMax: nb.mi },                 // milieu
        { yFloor: FLOOR,        hBase: 128, opacite: 0.88, nbMax: nb.av }                 // avant-scène
      ];

      // Distribue avec pool cyclique : si total > 8, réutilise des silhouettes
      // (mirror aléatoire les rend visuellement différentes même réutilisées)
      let pi = 0;
      PLANS.forEach(plan => {
        plan.sils = [];
        for (let k = 0; k < plan.nbMax; k++) {
          plan.sils.push({ ...pool[pi % pool.length], mirror: Math.random() > 0.5 });
          pi++;
        }
      });

      // Zones d'exclusion : panneaux à 9 %, 67 %, 86 % du viewport
      // SVG centré max-width:600px → on calcule l'x en coordonnées SVG
      const EXCL = [];
      if (window.innerWidth >= 901) {
        const svgW    = Math.min(window.innerWidth, 600);
        const svgLeft = (window.innerWidth - svgW) / 2;
        [0.09, 0.67, 0.86].forEach(pct => {
          const xSVG = (pct * window.innerWidth - svgLeft) / svgW * VW;
          const mg   = 30; // marge SVG de chaque côté
          if (xSVG + mg > 0 && xSVG - mg < VW)
            EXCL.push({ x1: Math.max(0, xSVG - mg), x2: Math.min(VW, xSVG + mg) });
        });
      }
      const collidePanneau = (x, sw) => EXCL.some(e => x < e.x2 && (x + sw) > e.x1);

      const GAP_INTRA = 9;
      const svgParts = [];

      // Lignes de sol (perspective)
      svgParts.push(
        '<line x1="0" y1="'+(VH*0.35).toFixed(0)+'" x2="'+VW+'" y2="'+(VH*0.35).toFixed(0)+'" stroke="rgba(255,255,255,.04)" stroke-width="1"/>',
        '<line x1="0" y1="'+(VH*0.65).toFixed(0)+'" x2="'+VW+'" y2="'+(VH*0.65).toFixed(0)+'" stroke="rgba(255,255,255,.05)" stroke-width="1"/>'
      );

      // Zones horizontales distinctes par plan (4 entrées = 4 plans)
      const ZONES = [
        { debut: 0.03, fin: 0.97 }, // très lointain : pleine largeur
        { debut: 0.03, fin: 0.52 }, // lointain      : gauche
        { debut: 0.48, fin: 0.96 }, // milieu        : droite
        { debut: 0.12, fin: 0.84 }  // avant-scène   : large spread
      ];

      // Rendu plan par plan (arrière → avant)
      PLANS.forEach((plan, planIdx) => {
        if (!plan.sils.length) return;

        const totalW = plan.sils.reduce((s, p) => s + p.w * (plan.hBase / p.h), 0)
                     + (plan.sils.length - 1) * GAP_INTRA;

        const z = ZONES[planIdx];
        const zoneStart = VW * z.debut;
        const zoneEnd   = VW * z.fin;
        const maxJitter = Math.max(0, (zoneEnd - zoneStart) - totalW);
        let x = zoneStart + Math.random() * maxJitter * 0.7;
        x = Math.max(6, Math.min(VW - totalW - 6, x));
        // Jusqu'à 8 tentatives pour éviter les panneaux
        for (let att = 0; att < 8 && collidePanneau(x, totalW); att++) {
          x = zoneStart + Math.random() * maxJitter;
          x = Math.max(6, Math.min(VW - totalW - 6, x));
        }

        plan.sils.forEach(p => {
          const sc = plan.hBase / p.h;
          const sw = p.w * sc;
          const sy = plan.yFloor - p.h * sc;
          const tr = p.mirror
            ? "translate("+sw.toFixed(1)+",0) scale(-"+sc.toFixed(5)+","+sc.toFixed(5)+")"
            : "scale("+sc.toFixed(5)+","+sc.toFixed(5)+")";

          const ombreRy = (1.0 + plan.hBase * 0.020).toFixed(1);
          svgParts.push(
            '<ellipse cx="'+(x+sw/2).toFixed(1)+'" cy="'+plan.yFloor.toFixed(1)+
            '" rx="'+(sw*0.42).toFixed(1)+'" ry="'+ombreRy+
            '" fill="rgba(0,0,0,'+(plan.opacite * 0.40).toFixed(2)+')"/>'
          );
          svgParts.push(
            '<g transform="translate('+x.toFixed(1)+','+sy.toFixed(1)+') '+tr+
            '" opacity="'+plan.opacite.toFixed(2)+'">'+
            '<path d="'+p.d+'" fill="rgba(4,2,0,1)" fill-rule="evenodd"/></g>'
          );
          x += sw + GAP_INTRA;
        });
      });

      return '<svg viewBox="0 0 '+VW+' '+VH+'" xmlns="http://www.w3.org/2000/svg" '+
        'aria-hidden="true" overflow="visible" style="display:block;width:100%;height:100%;">'+
        svgParts.join("")+"</svg>";
    }


    function ouvrirModal(toile) {
      document.getElementById('modalTitre').textContent = toile.titre || 'Sans titre';

      // Affiche un champ ou masque toute la ligne si valeur vide
      function setChamp(id, valeur) {
        const el = document.getElementById(id);
        const ligne = el && el.closest('.modal-ligne');
        if (valeur) {
          el.textContent = valeur;
          if (ligne) ligne.style.display = '';
        } else {
          if (ligne) ligne.style.display = 'none';
        }
      }

      setChamp('modalDate',      toile.date  || '');
      setChamp('modalStyle',     toile.style || '');
      setChamp('modalMateriaux',
        (toile.materiaux && toile.materiaux.length) ? toile.materiaux.join(', ') : '');

      // Dimensions : utilise largeur/hauteur (le champ "format" n'existe pas dans le JSON)
      const dim = toile.dimensions;
      let dimTexte = '';
      if (dim && dim.largeur && dim.hauteur) {
        dimTexte = dim.largeur + ' \u00d7 ' + dim.hauteur + ' cm';
        if (dim.type) dimTexte += '\u2002\u2014\u2002' + dim.type;
      }
      setChamp('modalDimensions', dimTexte);

      // Description
      const descLigne = document.getElementById('modalDescLigne');
      const descVal   = document.getElementById('modalDesc');
      if (toile.description) {
        descVal.textContent = toile.description;
        descLigne.style.display = '';
      } else {
        descLigne.style.display = 'none';
      }

      const wrap = document.getElementById('modalImageWrap');
      if (toile.photo) {
        const imgModal = document.createElement('img');
        var _mSrcJpg   = (/^https?:\/\//.test(toile.photo)) ? toile.photo : GALERIE_CFG.assetsBase + toile.photo;
        var _mSrcWebP  = /^https?:\/\//.test(toile.photo) ? toile.photo : _mSrcJpg.replace(/\.jpg$/i, '.webp');
        var _mSrcThumb = /^https?:\/\//.test(toile.photo) ? toile.photo : _mSrcJpg.replace(/\.jpg$/i, '-thumb.webp');
        imgModal.srcset = _mSrcThumb + ' 400w, ' + _mSrcWebP + ' 1200w';
        imgModal.sizes  = '(max-width: 600px) 400px, min(90vw, 1200px)';
        imgModal.src    = _mSrcJpg;
        imgModal.alt    = toile.titre || 'Toile';
        imgModal.decoding = 'async';
        imgModal.onerror = function() {
          const drap = creerDrapBlanc(); drap.style.minHeight = '260px';
          wrap.replaceChild(drap, this);
        };
        wrap.innerHTML = '';
        wrap.appendChild(imgModal);
      } else {
        wrap.innerHTML = '<div class="modal-placeholder-grand">' + toile.id + '</div>';
      }
      if (modalOverlay) modalOverlay.classList.add('visible');
      document.body.style.overflow = 'hidden';
    }

    function fermerModal() {
      if (modalOverlay) modalOverlay.classList.remove('visible');
      document.body.style.overflow = '';
    }

    var _mf = document.getElementById('modalFermer'); if (_mf) _mf.addEventListener('click', fermerModal);
    if (modalOverlay) modalOverlay.addEventListener('click', e => { if (e.target === modalOverlay) fermerModal(); });

    /* Swipe bas pour fermer le modal (mobile) */
    let swipeStartY = null;
    const modalContenu = document.querySelector('.modal-contenu');
    if (modalContenu) modalContenu.addEventListener('touchstart', e => { swipeStartY = e.touches[0].clientY; }, { passive:true });
    if (modalContenu) modalContenu.addEventListener('touchend', e => {
      if (swipeStartY === null) return;
      const dy = e.changedTouches[0].clientY - swipeStartY;
      if (dy > 80) fermerModal();
      swipeStartY = null;
    }, { passive:true });

    // ── Drap blanc — affiché quand une image est introuvable ────────
    var _drapCpt = 0;
    function creerDrapBlanc(largeur, hauteur) {
      var id = ++_drapCpt;
      var gf = 'dgf' + id, gv = 'dgv' + id; // IDs uniques par instance
      var el = document.createElement('div');
      Object.assign(el.style, {
        width:          largeur ? largeur + 'px' : '100%',
        height:         hauteur ? hauteur + 'px' : '100%',
        position:       'relative',
        overflow:       'hidden',
        display:        'flex',
        alignItems:     'center',
        justifyContent: 'center',
        flexShrink:     '0'
      });
      // SVG drapé : gradient horizontal (crêtes/vallées de plis) +
      //             lignes de pli en courbes de Bézier +
      //             fronces en haut (tissu sur le bord du cadre)
      el.innerHTML =
        '<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%"' +
        ' viewBox="0 0 200 300" preserveAspectRatio="xMidYMid slice"' +
        ' style="position:absolute;inset:0;display:block;">' +
        '<defs>' +
        '<linearGradient id="' + gf + '" x1="0" y1="0" x2="1" y2="0">' +
        '<stop offset="0"   stop-color="#a8a49c"/>' +
        '<stop offset=".04" stop-color="#bfbbb3"/>' +
        '<stop offset=".11" stop-color="#f3efe6"/>' +
        '<stop offset=".17" stop-color="#e6e1d7"/>' +
        '<stop offset=".24" stop-color="#c8c4bc"/>' +
        '<stop offset=".32" stop-color="#d8d4ca"/>' +
        '<stop offset=".40" stop-color="#f1ece4"/>' +
        '<stop offset=".48" stop-color="#e4dfd5"/>' +
        '<stop offset=".55" stop-color="#c6c2ba"/>' +
        '<stop offset=".63" stop-color="#d6d2c8"/>' +
        '<stop offset=".71" stop-color="#f0ebe3"/>' +
        '<stop offset=".79" stop-color="#e2ddd3"/>' +
        '<stop offset=".87" stop-color="#c8c4bc"/>' +
        '<stop offset="1"   stop-color="#a4a09a"/>' +
        '</linearGradient>' +
        '<linearGradient id="' + gv + '" x1="0" y1="0" x2="0" y2="1">' +
        '<stop offset="0"   stop-color="rgba(0,0,0,.22)"/>' +
        '<stop offset=".09" stop-color="rgba(0,0,0,.06)"/>' +
        '<stop offset=".68" stop-color="rgba(0,0,0,0)"/>' +
        '<stop offset="1"   stop-color="rgba(0,0,0,.10)"/>' +
        '</linearGradient>' +
        '</defs>' +
        '<rect width="200" height="300" fill="url(#' + gf + ')"/>' +
        '<rect width="200" height="300" fill="url(#' + gv + ')"/>' +
        // Lignes de pli — courbes de Bézier légèrement déviées (tissu naturel)
        '<path d="M22,0 C20,75 24,155 21,235 C19,268 22,288 20,300" stroke="rgba(0,0,0,.10)" stroke-width="1.5" fill="none"/>' +
        '<path d="M44,0 C46,65 43,148 45,228 C47,262 44,284 46,300" stroke="rgba(255,255,255,.42)" stroke-width="2" fill="none"/>' +
        '<path d="M80,0 C78,85 82,165 80,248 C78,272 81,289 79,300" stroke="rgba(0,0,0,.09)" stroke-width="1.5" fill="none"/>' +
        '<path d="M102,0 C104,78 101,158 103,240 C105,268 102,286 104,300" stroke="rgba(255,255,255,.40)" stroke-width="2" fill="none"/>' +
        '<path d="M136,0 C134,72 138,152 136,234 C134,265 137,284 135,300" stroke="rgba(0,0,0,.09)" stroke-width="1.5" fill="none"/>' +
        '<path d="M160,0 C162,82 159,162 161,244 C163,270 160,288 162,300" stroke="rgba(255,255,255,.36)" stroke-width="1.5" fill="none"/>' +
        // Fronces du bord supérieur : tissu plié sur le cadre
        '<path d="M0,0 L200,0 L200,16' +
        ' C188,12 176,18 164,13 C152,18 140,11 128,15' +
        ' C116,10 104,17 92,12 C80,17 68,10 56,14' +
        ' C44,9 32,16 20,12 C10,16 0,12 0,12 Z"' +
        ' fill="rgba(0,0,0,.13)"/>' +
        '</svg>';
      // Étiquette cartel — par-dessus le SVG
      var etiq = document.createElement('div');
      Object.assign(etiq.style, {
        position:      'relative',
        zIndex:        '1',
        background:    'rgba(255,255,255,.88)',
        border:        '0.5px solid rgba(0,0,0,.18)',
        borderRadius:  '2px',
        padding:       '4px 10px',
        fontSize:      '9px',
        fontFamily:    "'Playfair Display',Georgia,serif",
        fontStyle:     'italic',
        color:         '#5a4f42',
        textAlign:     'center',
        letterSpacing: '.06em',
        boxShadow:     '0 1px 4px rgba(0,0,0,.12)',
        whiteSpace:    'nowrap',
        maxWidth:      '85%'
      });
      etiq.textContent = 'En cours de nettoyage';
      el.appendChild(etiq);
      return el;
    }


/* ══════════════════════════════════════════════════════════════
   INIT GALERIE MULTI-TYPE
   Chaque renderer s'enregistre via GALERIE_RENDERERS[type]
   ══════════════════════════════════════════════════════════════ */
const GALERIE_RENDERERS = {};

function initGalerie() {
  /* Mode édition — cacher tout sauf la salle, plein écran */
  if (window._GALERIE_EDIT) {
    var editStyle = document.createElement('style');
    editStyle.textContent =
      '.bandeau-invite,.entete,.nav-pages,.controles,.btn-musique,.barre-navigation,.nav-mobile,.dots,.nav-retour,.retour-plan,.panneau-nav,.plaque-nav,.galerie-footer,.nav-cote,.salle-titre,.nom-salle,.porte-nav,.porte-mur{display:none!important;}' +
      'body{margin:0!important;padding:0!important;overflow:hidden!important;}' +
      '.galerie-principale{padding:0!important;margin:0!important;}' +
      /* Chaîne flex complète : galerie.css n'est pas chargé en édition, donc
         .conteneur-salles n'a ni hauteur ni flex → la salle n'a pas de hauteur
         définie et zone-basse/plancher en flex:1 ne remplissent pas (le fond
         « mur de la pièce » ressort sous le sol). On reconstruit la chaîne sans
         dépendre de 100vh/100svh (peu fiables en iframe). */
      '.conteneur-salles{width:100%!important;height:100%!important;flex:1 1 auto!important;min-height:0!important;display:flex!important;flex-direction:column!important;transform:none!important;transition:none!important;}' +
      '.salle{width:100%!important;display:flex!important;flex-direction:column!important;}' +
      '.salle.salle-sculpture{flex:1 1 auto!important;height:auto!important;min-height:100dvh!important;padding-bottom:0!important;}' +
      '.salle-sculpture .mur-inferieur{flex:0 0 auto!important;}' +
      '.salle-sculpture .zone-basse{flex:1 1 auto!important;min-height:0!important;}' +
      '.salle-sculpture .plancher-sol{flex:1 1 auto!important;min-height:0!important;max-height:none!important;}';
    document.head.appendChild(editStyle);
  }

  /* Si l'admin a injecté les données (window._GALERIE_INJECTED), les utiliser
     directement au lieu de fetch — évite le cache CDN périmé après sauvegarde.
     Format historique : { toiles: <data mono-type>, salles: {...} }
     Adapté en dict {type: data} pour rester compat avec le nouveau code. */
  var _dataPromise;
  if (window._GALERIE_INJECTED && window._GALERIE_INJECTED.toiles && window._GALERIE_INJECTED.salles) {
    var inj = window._GALERIE_INJECTED.toiles;
    var injType = (inj && inj.pieces) ? 'sculpture' : 'peinture';
    var injDict = {}; injDict[injType] = inj;
    _dataPromise = Promise.resolve([injDict, window._GALERIE_INJECTED.salles]);
  } else {
    _dataPromise = Promise.all([
      _chargerOeuvres(),
      fetch(GALERIE_CFG.salles + '?v=' + Date.now()).then(r => { if (!r.ok) throw new Error(r.status); return r.json(); })
    ]);
  }

  _dataPromise
  .then(([oeuvresParType, sData]) => {
    const salles = sData.salles || [];
    /* Surcouche locale (éditeur in-app hors ligne) : si l'éditeur est chargé,
       il fusionne ses modifications locales par-dessus salles.json et mémorise
       une copie « base ». Aucun effet si l'éditeur n'est pas présent. */
    if (typeof window._FF_APPLY_LOCAL_LAYOUT === 'function') {
      try { window._FF_APPLY_LOCAL_LAYOUT(salles); }
      catch (e) { console.warn('[local-edit]', e); }
    }
    /* Filtre visibilité : la galerie publique n'affiche que les salles dont
       visible !== false. En mode édition/arrangeur (_GALERIE_EDIT), on garde
       TOUTES les salles pour que l'admin puisse encore agencer une salle
       masquée. L'admin (apercu compris) sélectionne les salles via les chips,
       pas via ce rendu, donc filtrer ici ne gêne pas l'édition. */
    let sallesRendues = window._GALERIE_EDIT
      ? salles
      : salles.filter(s => s.visible !== false);
    /* Cas « toutes masquées » (hors édition) : on injecte une salle « travaux »
       de repli — le visiteur voit un message au lieu d'un écran vide, et la nav
       ne divise pas par TOTAL_SALLES = 0. */
    if (!window._GALERIE_EDIT && sallesRendues.length === 0) {
      sallesRendues = [{
        id: '__travaux__',
        nom: 'Galerie en réaménagement',
        _message: 'La galerie est momentanément en cours de réaménagement. Merci de revenir bientôt \u2014 les salles seront de nouveau visibles très prochainement.'
      }];
    }
    TOTAL_SALLES = sallesRendues.length;
    const _hm = window.location.hash.match(/^#salle-(\d+)$/);
    conteneur.style.width = (TOTAL_SALLES * 100) + '%';

    sallesRendues.forEach((salle, si) => {
      /* Salle « travaux » synthétique : message centré, ni renderer ni portes. */
      if (salle._message) {
        const salleDiv = document.createElement('div');
        salleDiv.className = 'salle salle-message';
        salleDiv.id = 'salle-travaux';
        salleDiv.style.width = (100 / TOTAL_SALLES) + '%';
        salleDiv.setAttribute('aria-label', salle.nom);
        const nomEl = document.createElement('p');
        nomEl.className = 'nom-salle';
        nomEl.textContent = salle.nom;
        salleDiv.appendChild(nomEl);
        const msg = document.createElement('p');
        msg.textContent = salle._message;
        msg.style.cssText = 'color:var(--text-doux,#c9b98f);font-style:italic;text-align:center;padding:2rem 1.5rem;max-width:34rem;margin:auto;line-height:1.7;';
        salleDiv.appendChild(msg);
        conteneur.appendChild(salleDiv);
        return;
      }
      const type = salle.type || 'peinture';
      const renderer = GALERIE_RENDERERS[type];
      if (!renderer) {
        console.warn('Pas de renderer pour le type:', type);
        return;
      }
      /* Données du type de la salle. En multi-types, on filtre AVANT
         de passer au renderer pour éviter toute collision d'id entre
         peinture et sculpture. Si le type n'a pas été chargé, la salle
         reste sans œuvres mais le décor est rendu. */
      const tData = oeuvresParType[type] || (type === 'sculpture'
        ? { gabarits: [], pieces: [] }
        : { tailles: [], toiles: [] });

      const salleDiv = document.createElement('div');
      salleDiv.className = 'salle';
      salleDiv.id        = 'salle' + salle.id;
      salleDiv.style.width = (100 / TOTAL_SALLES) + '%';
      salleDiv.setAttribute('aria-label', salle.nom || ('Salle ' + salle.id));

      const nomEl = document.createElement('p');
      nomEl.className   = 'nom-salle';
      nomEl.textContent = salle.nom || ('Salle ' + NOMS_ROMAINS[salle.id - 1]);
      salleDiv.appendChild(nomEl);

      renderer(salleDiv, salle, si, sallesRendues, tData);

      conteneur.appendChild(salleDiv);
    });

    mettreAJourNav();

    const hashId = parseInt((_hm || [])[1]);
    if (hashId) {
      const hashIdx = sallesRendues.findIndex(s => s.id === hashId) + 1;
      const cible   = hashIdx > 0 ? hashIdx : 1;
      conteneur.style.transition = 'none';
      allerSalle(cible);
      conteneur.getBoundingClientRect();
      requestAnimationFrame(() => requestAnimationFrame(() => { conteneur.style.transition = ''; }));
    }
    /* Mode édition — activer le drag sur les socles.
       Le renderer édition (galerie-edit.html) est mono-type, on lui passe
       le tData du type de la salle active. */
    if (window._GALERIE_EDIT && typeof window._initEditDrag === 'function') {
      var typeActif = (salles[0] && salles[0].type) || 'peinture';
      var tDataActif = oeuvresParType[typeActif] || { tailles: [], toiles: [] };
      requestAnimationFrame(function() { window._initEditDrag(salles, tDataActif); });
    }
  })
  .catch(err => {
    console.error('Galerie init:', err);
    conteneur.innerHTML = '<p style="color:var(--text-doux);font-style:italic;padding:2rem;">Données non disponibles.</p>';
  });
}
